import{at as e,it as t,n,vt as r}from"./chunks/framework.UwwvkjGo.js";var i=JSON.parse(`{"title":"Brand","description":"","frontmatter":{},"headers":[],"relativePath":"brand/index.md","filePath":"brand/index.md"}`),a={name:`brand/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<div><h1 id="brand" tabindex="-1">Brand <a class="header-anchor" href="#brand" aria-label="Permalink to “Brand”">​</a></h1><p>How JSPrismarine looks and sounds. The docs site implements this guide, and the <a href="https://jsprismarine.github.io/JSPrismarine/brand-kit" target="_blank" rel="noreferrer">brand kit</a> renders every color, the mark and each component live from the same source.</p><table tabindex="0"><thead><tr><th>What</th><th>Where</th></tr></thead><tbody><tr><td>Palette</td><td><code>tools/docs/site/.vitepress/theme/tokens.ts</code></td></tr><tr><td>Mark geometry</td><td><code>tools/docs/site/.vitepress/theme/prism.ts</code></td></tr><tr><td>Derived shades and sizes</td><td><code>tools/docs/site/.vitepress/theme/brand.css</code></td></tr><tr><td>Components</td><td><code>tools/docs/site/.vitepress/theme/components/</code></td></tr><tr><td>Project facts</td><td><code>tools/docs/site/project.data.mts</code></td></tr></tbody></table><h2 id="position" tabindex="-1">Position <a class="header-anchor" href="#position" aria-label="Permalink to “Position”">​</a></h2><p>JSPrismarine is the Bedrock server you run, own and build on. It is a product people choose, not a library index. The brand is flat, bold and direct: big type, solid color blocks, hard edges, and real commands and numbers instead of decoration.</p><p>Four audiences use the site. Each page should make clear which one it serves:</p><table tabindex="0"><thead><tr><th>Audience</th><th>Wants</th><th>Landing tab</th></tr></thead><tbody><tr><td>Players</td><td>Join a server and know what works</td><td>I play</td></tr><tr><td>Hosts</td><td>Install, configure and operate it</td><td>I host</td></tr><tr><td>Add-on devs</td><td>Packs, Molang and the package API</td><td>I build add-ons</td></tr><tr><td>Contributors</td><td>Clone, change, test and ship</td><td>I contribute</td></tr></tbody></table><h2 id="color" tabindex="-1">Color <a class="header-anchor" href="#color" aria-label="Permalink to “Color”">​</a></h2><p>The accent is <code>#5ca48a</code>, shared with the JSPrismarine website. Every other color supports it.</p><table tabindex="0"><thead><tr><th>Token</th><th>Hex</th><th>Use</th></tr></thead><tbody><tr><td><code>--jsp-accent</code></td><td><code>#5ca48a</code></td><td>Primary accent: buttons, highlights, active states.</td></tr><tr><td><code>--jsp-forest</code></td><td><code>#003829</code></td><td>Dark brand surface and light-mode link color.</td></tr><tr><td><code>--jsp-deep</code></td><td><code>#00281d</code></td><td>Darkest surface: tile backgrounds and shadows.</td></tr><tr><td><code>--jsp-mint</code></td><td><code>#a9d9c6</code></td><td>Body text on forest and the light facet of the mark.</td></tr><tr><td><code>--jsp-cream</code></td><td><code>#efe9da</code></td><td>Light surface and text on dark.</td></tr><tr><td><code>--jsp-ink</code></td><td><code>#0b1713</code></td><td>Text on light and the terminal surface.</td></tr><tr><td><code>--jsp-signal</code></td><td><code>#ff6b3d</code></td><td>Spot color for prompts, cursors and the core of the mark.</td></tr></tbody></table><p><code>tokens.ts</code> is the authority for these values. The site config writes them into the page head as the <code>--jsp-*</code> custom properties and builds the favicon from them, and <code>brand.css</code> mixes the supporting shades (terminal chrome, progress tracks, page backgrounds) from them with <code>color-mix</code>. If this table and <code>tokens.ts</code> disagree, <code>tokens.ts</code> wins and this table is out of date.</p><p>Rules:</p><ul><li>Surfaces are flat. No gradients, glows, blurs or translucent glass.</li><li>Signal orange marks small things: a prompt, a cursor, the core of the mark, a focus ring. A page may also use it for one solid block. It is never a link color and never a body text color.</li><li>Text on <code>--jsp-accent</code> is <code>--jsp-forest</code>. Text on <code>--jsp-signal</code> is <code>--jsp-ink</code>.</li><li>Keep body text at WCAG AA contrast or better against its surface.</li></ul><h2 id="type" tabindex="-1">Type <a class="header-anchor" href="#type" aria-label="Permalink to “Type”">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Family</th><th>Weights</th><th>Notes</th></tr></thead><tbody><tr><td>Display</td><td>Bricolage Grotesque</td><td>500, 800</td><td>Tight tracking (<code>-0.04em</code> and below).</td></tr><tr><td>Mono</td><td>JetBrains Mono</td><td>400, 700</td><td>Commands, labels, logs and code.</td></tr></tbody></table><p>Headlines are set heavy and tight, in sentence case, and are allowed to be very large. Small labels are mono, uppercase and letter-spaced. System fonts are the fallback when the web fonts do not load.</p><h2 id="mark" tabindex="-1">Mark <a class="header-anchor" href="#mark" aria-label="Permalink to “Mark”">​</a></h2><p>The mark is a prism: a triangle split down the middle into an <code>--jsp-accent</code> face and a <code>--jsp-mint</code> face, with a small <code>--jsp-signal</code> triangle at its core whose right half is shaded with ink.</p><ul><li>Use <code>PrismMark</code> rather than redrawing it. The favicon and the nav logo come from the same geometry in <code>prism.ts</code>.</li><li>Keep clear space of half the mark&#39;s width on every side.</li><li>Do not rotate, outline, add shadows or recolor the faces. The mark works unchanged on cream, forest and ink, so it has no inverted version.</li><li>The wordmark is <code>JSPrismarine</code>: one word, camel case, set in Bricolage Grotesque 800.</li></ul><h2 id="shape-and-motion" tabindex="-1">Shape and motion <a class="header-anchor" href="#shape-and-motion" aria-label="Permalink to “Shape and motion”">​</a></h2><ul><li>Corners are <code>14px</code> on panels (<code>--jsp-radius-panel</code>) and <code>10px</code> on controls (<code>--jsp-radius-control</code>). Pills are fully round.</li><li>Primary actions carry a hard offset shadow (<code>4px 4px 0</code>, no blur). It shrinks on hover and disappears on press, so the button reads as pushed in.</li><li>Grids are tight: <code>10px</code> gaps (<code>--jsp-gap</code>) between solid blocks.</li><li>Every control shows a signal-orange focus ring when reached by keyboard.</li><li>Motion is short and mechanical. Honor <code>prefers-reduced-motion</code> by stopping tickers and cursors.</li></ul><h2 id="voice" tabindex="-1">Voice <a class="header-anchor" href="#voice" aria-label="Permalink to “Voice”">​</a></h2><ul><li>State what the thing does. &quot;One binary to host it.&quot; beats &quot;A powerful solution for hosting.&quot;</li><li>Prefer real commands, file names and numbers to adjectives. Never show a number the repository cannot back.</li><li>Address the reader directly and keep sentences short.</li><li>American English, sentence case headings, no exclamation marks, no emoji.</li></ul><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to “Components”">​</a></h2><p>The docs theme registers these Vue components globally, so any site page can use them without an import. Pages staged from <code>docs/</code> render as plain Markdown, so use the components from site-owned pages such as <code>tools/docs/site/index.md</code> and <code>tools/docs/site/brand-kit.md</code>.</p><table tabindex="0"><thead><tr><th>Component</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PrismMark</code></td><td>The mark as inline SVG, at any size.</td></tr><tr><td><code>BrandButton</code></td><td>Primary and outline buttons with the hard shadow.</td></tr><tr><td><code>TerminalWindow</code></td><td>A server console frame. Each <code>t-line</code> span in the slot is a line.</td></tr><tr><td><code>AudienceTabs</code></td><td>Keyboard-navigable tabs with a pitch, a snippet and links each.</td></tr><tr><td><code>BentoGrid</code>, <code>BentoTile</code></td><td>Solid color tiles for short claims or figures.</td></tr><tr><td><code>ParityBars</code></td><td>The behavior parity score and bars, counted as the tracker counts.</td></tr><tr><td><code>CopyButton</code></td><td>Copies a command to the clipboard.</td></tr><tr><td><code>Ticker</code></td><td>A looping banner of short phrases.</td></tr></tbody></table><h2 id="content-comes-from-the-repository" tabindex="-1">Content comes from the repository <a class="header-anchor" href="#content-comes-from-the-repository" aria-label="Permalink to “Content comes from the repository”">​</a></h2><p>The landing page states no fact that the repository already records. <code>project.data.mts</code> reads these at build time:</p><ul><li>the server version;</li><li>the published packages;</li><li>the Node and pnpm requirements;</li><li>the supported protocols and Minecraft releases;</li><li>the default port and online mode.</li></ul><p>The build fails when a command, package or source pattern the page relies on disappears. The terminal preview uses the server&#39;s real startup log lines. <code>ParityBars</code> reads the tracker snapshot and shows the gameplay behavior score that the parity tracker page leads with, not the data-table pass rate. To add a claim to the page, add it to the loader rather than typing the value into a component.</p><h2 id="changing-the-brand" tabindex="-1">Changing the brand <a class="header-anchor" href="#changing-the-brand" aria-label="Permalink to “Changing the brand”">​</a></h2><p>Change a color in <code>tokens.ts</code>, a shape in <code>prism.ts</code>, and a derived value in <code>brand.css</code>, never a hex value in a component. Update this guide in the same commit when a token, font or rule changes.</p></div>`,1)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};